using System;
using System.Collections.Generic;

public class BoyerMooreVoting
{
    public static string FindMajorityElement(int[] array)
    {
        string majorityElement = "";

        // Step 1: Calculate the voting power of each element
        Dictionary<int, int> votingPower = new Dictionary<int, int>();
        for (int i = 0; i < array.Length; i++)
        {
            if (array.Count(x => x == i) > 1)
            {
                int count = array.Count(x => x == i);
                votingPower[i] = count;
            }
        }

        // Step 2: Sort the elements in descending order of their voting power
        List<int> sortedElementList = new List<int>(votingPower.Keys);
        sortedElementList.Sort(compareElements);

        // Step 3: Compare the elements and find the majority element
        foreach (int element in sortedElementList)
        {
            if (votingPower[element] > (array.Length / 2))
            {
                if (majorityElement == "")
                {
                    majorityElement = element.ToString();
                }
                else
                {
                    Console.WriteLine("Majority element not found");
                    break;
                }
            }
        }

        if (majorityElement == "")
        {
            Console.WriteLine("No majority element found");
        }
        else
        {
            Console.WriteLine("Majority element: " + majorityElement);
        }

        return majorityElement;
    }

    private static int compareElements(int x, int y)
    {
        if (votingPower[y] > votingPower[x])
            return -1;
        else if (votingPower[y] < votingPower[x])
            return 1;
        else
            return 0;
    }
}
