    public static List<int> FindTop2MostOccurringElements(int[] array)
    {
        List<int> top2MostOccurringElements = new List<int>();

        // Step 1: Calculate the voting power of each element
        Dictionary<int, int> votingPower = new Dictionary<int, int>();
        foreach (int element in array)
        {
            if (votingPower.ContainsKey(element))
            {
                votingPower[element]++;
            }
            else
            {
                votingPower[element] = 1;
            }
